def solve(data):
    pattern = data['pattern']
    text = data['text']

    # Edge cases: empty or minimal inputs
    if not pattern or not text:
        return True

    # Boundary values: single character patterns
    if len(pattern) == 1:
        return text == pattern

    # Duplicates: treat consecutive identical characters as a single match
    if len(pattern) > 1 and pattern[0] == pattern[1]:
        return solve({'pattern': pattern[1:], 'text': text})

    # Large inputs: use dynamic programming
    m, n = len(pattern), len(text)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[0][0] = True

    for i in range(1, m + 1):
        if pattern[i - 1] == '*':
            dp[i][0] = dp[i - 1][0]
        else:
            break

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if pattern[i - 1] == '*':
                dp[i][j] = dp[i - 1][j] or dp[i][j - 1]
            elif pattern[i - 1] == '?':
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = dp[i - 1][j - 1] and pattern[i - 1] == text[j - 1]

    return dp[m][n]

def solve(data):
    a = data['a']
    b = data['b']

    # If both strings are empty, no operations needed
    if not a and not b:
        return 0

    # Initialize DP table with dimensions (len(a)+1) x (len(b)+1)
    dp = [[0] * (len(b)+1) for _ in range(len(a)+1)]

    # Fill the DP table
    for i in range(1, len(a)+1):
        for j in range(1, len(b)+1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1]
            else:
                dp[i][j] = min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1]) + 1

    # The result is the value in the bottom-right corner of the DP table
    return dp[-1][-1]

